<?php declare( strict_types=1 ); namespace Inc\Services\Exam; use Inc\DTO\Assessment\AttemptInputDTO; use Inc\Enums\Assessment\AttemptStatus; use Inc\Repositories\WPDBRepositories\AssessmentAttemptRepository; use Inc\Repositories\WPDBRepositories\ExamParticipationRepository; class ExamAttemptService { private AssessmentAttemptRepository $attemptRepo; private ExamParticipationRepository $participationRepo; public function __construct( ?AssessmentAttemptRepository $attemptRepo = null, ?ExamParticipationRepository $participationRepo = null ) { $this->attemptRepo = $attemptRepo ?? new AssessmentAttemptRepository(); $this->participationRepo = $participationRepo ?? new ExamParticipationRepository(); } public function createExamAttempt( int $participationId, int $assessmentId, int $registrationId, string $scheduledAt, string $plannedEndAt ): int { $participation = $this->participationRepo->find( $participationId ); if ( ! $participation ) { throw new \Exception( 'Участие не найдено' ); } $dto = new AttemptInputDTO( assessmentId: $assessmentId, studentPersonId: $participation->personId, groupId: null, attemptNumber: 1, startedAt: current_time( 'mysql', true ), deadlineAt: $plannedEndAt, status: AttemptStatus::InProgress, groupLessonId: null, examParticipationId: $participationId, examRegistrationId: $registrationId, ); $attemptId = $this->attemptRepo->create( $dto ); $this->participationRepo->update( $participationId, [ 'current_attempt_id' => $attemptId, ] ); return $attemptId; } public function approveExamAttempt( int $attemptId, int $approvedByUserId ): bool { return $this->attemptRepo->approve( $attemptId, $approvedByUserId, current_time( 'mysql', true ) ); } public function submitExamAttempt( int $attemptId, string $status = 'submitted' ): bool { return $this->attemptRepo->update( $attemptId, [ 'status' => $status, 'submitted_at' => current_time( 'mysql', true ), ] ); } public function markAsGraded( int $attemptId, float $totalScore, float $maxScore ): bool { return $this->attemptRepo->update( $attemptId, [ 'status' => 'graded', 'total_score' => $totalScore, 'max_score' => $maxScore, 'graded_by_user_id' => get_current_user_id(), ] ); } }
